const wb = $('Webhook FollowUp').first().json.body;
let parsed = { enviar: false, texto: '' };
try {
  const r = $input.first().json;
  const c = r && r.choices && r.choices[0] && r.choices[0].message ? r.choices[0].message.content : null;
  if (c) parsed = JSON.parse(c);
} catch (e) {}
let text = (parsed.texto || '').trim();
text = text.replace(/[¿¡]/g, '');
if (text && /\p{Ll}/u.test(text[0])) text = text.charAt(0).toUpperCase() + text.slice(1);
const enviar = parsed.enviar === true && text.length > 0;
return [{ json: { telefono: wb.telefono, instance: wb.instance, text, enviar } }];

